package dev.hoi.client.screen;

import dev.hoi.protocol.*;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.input.KeyEvent;

public final class ScreenArmyHeadquartersTest {
    private ScreenArmyHeadquartersTest() {}
    public static void run(ClientGameTestContext context,ProtocolMenuView menu)throws java.io.IOException{
        String directory=System.getenv("HOI_HEADQUARTERS_PREVIEW");if(directory==null)throw new AssertionError("Authoritative HQ fixtures are required");
        for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
            context.getInput().resizeWindow(size[0],size[1]);context.runOnClient(client->client.options.guiScale().set(2));
            for(String stage:List.of("list","draft","saved","preview","conflict")){
                var view=new ProtocolIndustryPayloads.Response(Files.readString(Path.of(directory,"headquarters-"+stage+".json"))).view();var requests=new ArrayList<ProtocolIndustryPayloads.Request>();
                context.setScreen(()->new ScreenMenu(menu,ProtocolMenuTab.OFFICER_CORPS,()->{}));context.waitTicks(2);
                context.runOnClient(client->{var parent=client.gui.screen();client.gui.setScreen(new ScreenArmyHeadquarters(parent,view.session(),view,requests::add));});context.waitTicks(3);
                context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();for(var child:screen.children())if(child instanceof AbstractWidget widget)if(widget.getX()<0||widget.getY()<0||widget.getX()+widget.getWidth()>screen.width||widget.getY()+widget.getHeight()>screen.height)throw new AssertionError("HQ widget escaped GUI2 bounds: "+stage);if(!requests.isEmpty())throw new AssertionError("Rendering must not mutate HQ state");if(view.headquarters().draft()!=null&&screen.children().stream().filter(c->c instanceof dev.hoi.client.ui.UiHoverRegion r&&r.getMessage().getString().startsWith("HQ 지역 변동치")).count()!=11)throw new AssertionError("HQ requires eleven source terrain icons");if(view.headquarters().draft()!=null&&(view.headquarters().details().stats().size()!=28||screen.children().stream().filter(dev.hoi.client.ui.UiHoverRegion.class::isInstance).count()!=39))throw new AssertionError("HQ requires all 28 dynamic combat stats plus eleven terrain tooltips");});
                context.takeScreenshot("hoi-hq-"+stage+"-"+size[0]+"x"+size[1]+"-gui2");
                if(stage.equals("draft")){
                    context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();var edit=screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).findFirst().orElseThrow();edit.setValue("HQ edited name");screen.onClose();if(!requests.isEmpty())throw new AssertionError("Dirty close must ask before discarding");press(screen,"계속 편집");if(!requests.isEmpty())throw new AssertionError("Cancel discard must preserve the draft");press(screen,"저장");if(requests.size()!=1||requests.getFirst().action()!=ProtocolIndustryPayloads.Action.HQ_SAVE||!requests.getFirst().item().equals("HQ edited name"))throw new AssertionError("HQ save must use the current draft name exactly once");screen.onClose();if(requests.size()!=1)throw new AssertionError("Pending save must prevent duplicate actions");});
                }
                if(stage.equals("conflict")){
                    context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();if(screen.allowsMovement())throw new AssertionError("Designer must block world and army input");String unit=view.headquarters().labels().get(view.headquarters().draft().battalions().getFirst());press(screen,unit);if(!requests.isEmpty())throw new AssertionError("Opening the picker must not mutate the draft");});context.waitTicks(2);
                    context.takeScreenshot("hoi-hq-picker-"+size[0]+"x"+size[1]+"-gui2");
                    int[] hover=new int[2];context.runOnClient(client->{var b=button((ScreenArmyHeadquarters)client.gui.screen(),view.headquarters().labels().get("hq_light_armor"));double scale=client.getWindow().getGuiScale();hover[0]=(int)((b.getX()+b.getWidth()/2.0)*scale);hover[1]=(int)((b.getY()+b.getHeight()/2.0)*scale);});context.getInput().setCursorPos(hover[0],hover[1]);context.waitTicks(8);context.takeScreenshot("hoi-hq-candidate-delta-"+size[0]+"x"+size[1]+"-gui2");context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();var tip=screen.detailTooltip();if(tip==null||tip.x()<0||tip.y()<0||tip.x()+tip.width()>screen.width||tip.y()+tip.height()>screen.height)throw new AssertionError("HQ candidate tooltip clipped");if(tip.maxScroll()>0){screen.mouseScrolled(tip.x()+2,tip.y()+2,0,-2);if(!requests.isEmpty())throw new AssertionError("Tooltip scroll must not select candidate");}});context.waitTicks(2);context.runOnClient(client->{var tip=((ScreenArmyHeadquarters)client.gui.screen()).detailTooltip();if(tip.maxScroll()>0&&tip.scroll()==0)throw new AssertionError("HQ tooltip scroll did not advance");});context.takeScreenshot("hoi-hq-candidate-scrolled-"+size[0]+"x"+size[1]+"-gui2");context.getInput().setCursorPos(size[0]-2,size[1]-2);context.waitTicks(2);
                    context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();screen.keyPressed(new KeyEvent(com.mojang.blaze3d.platform.InputConstants.KEY_ESCAPE,0,0));if(!requests.isEmpty())throw new AssertionError("Esc in picker must only close picker");press(screen,view.headquarters().labels().get(view.headquarters().draft().battalions().getFirst()));press(screen,view.headquarters().labels().get("hq_light_armor"));if(requests.size()!=1||requests.getFirst().action()!=ProtocolIndustryPayloads.Action.HQ_SLOT||!requests.getFirst().item().equals("hq_light_armor")||!requests.getFirst().other().equals("line")||requests.getFirst().amount()!=0)throw new AssertionError("Picker must send the selected HQ slot once");screen.onClose();if(requests.size()!=1)throw new AssertionError("Pending selection must block close");});
                }
                if(stage.equals("saved"))context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();screen.update(ProtocolIndustryView.revoked(view.session(),"권한 만료"));if(client.gui.screen() instanceof ScreenArmyHeadquarters)throw new AssertionError("Revision-zero revocation must close the private HQ screen");});
                if(stage.equals("list"))context.runOnClient(client->{press((ScreenArmyHeadquarters)client.gui.screen(),"새 설계");if(requests.size()!=1||requests.getFirst().action()!=ProtocolIndustryPayloads.Action.HQ_NEW)throw new AssertionError("New HQ draft must use the existing authoritative industry session");});
                if(stage.equals("preview")){
                    int[] point=new int[2];context.runOnClient(client->{var screen=client.gui.screen();var region=screen.children().stream().filter(c->c instanceof dev.hoi.client.ui.UiHoverRegion r&&r.getMessage().getString().equals("HQ 지역 변동치 · forest")).map(dev.hoi.client.ui.UiHoverRegion.class::cast).findFirst().orElseThrow();double scale=client.getWindow().getGuiScale();point[0]=(int)((region.getX()+region.getWidth()/2.0)*scale);point[1]=(int)((region.getY()+region.getHeight()/2.0)*scale);});context.getInput().setCursorPos(point[0],point[1]);context.waitTicks(8);context.takeScreenshot("hoi-hq-terrain-tooltip-"+size[0]+"x"+size[1]+"-gui2");context.getInput().setCursorPos(size[0]-2,size[1]-2);context.waitTicks(2);
                }
                if(stage.equals("preview"))context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();if(button(screen,"저장").active)throw new AssertionError("Unknown composition cost cannot be saved as zero");screen.onClose();press(screen,"초안 버리기");if(requests.size()!=1||requests.getFirst().action()!=ProtocolIndustryPayloads.Action.HQ_DISCARD)throw new AssertionError("Discard must affect only the transient draft");});
            }
        }
        var draft=new ProtocolIndustryPayloads.Response(Files.readString(Path.of(directory,"headquarters-draft.json"))).view();
        for(boolean remove:List.of(false,true)){
            var requests=new ArrayList<ProtocolIndustryPayloads.Request>();context.setScreen(()->new ScreenArmyHeadquarters(null,draft.session(),draft,requests::add));context.waitTicks(2);
            context.runOnClient(client->{var screen=(ScreenArmyHeadquarters)client.gui.screen();press(screen,remove?draft.headquarters().labels().get(draft.headquarters().draft().battalions().getFirst()):"+");if(!requests.isEmpty())throw new AssertionError("HQ picker must not send a mutation");press(screen,remove?"제거":draft.headquarters().labels().get("hq_infantry"));if(requests.size()!=1||requests.getFirst().action()!=ProtocolIndustryPayloads.Action.HQ_SLOT||requests.getFirst().amount()!=(remove?0:2)||!requests.getFirst().other().equals("line")||!requests.getFirst().item().equals(remove?"":"hq_infantry"))throw new AssertionError("HQ add/remove must use the exact selected slot");});
        }
        context.setScreen(()->null);
    }
    private static Button button(ScreenArmyHeadquarters screen,String label){return screen.children().stream().filter(Button.class::isInstance).map(Button.class::cast).filter(b->b.getMessage().getString().equals(label)).findFirst().orElseThrow(()->new AssertionError("Missing HQ button "+label));}
    private static void press(ScreenArmyHeadquarters screen,String label){var button=button(screen,label);if(!button.active)throw new AssertionError("HQ button inactive "+label);var event=new net.minecraft.client.input.MouseButtonEvent(button.getX()+button.getWidth()/2.0,button.getY()+button.getHeight()/2.0,new net.minecraft.client.input.MouseButtonInfo(com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_LEFT,0));if(!screen.mouseClicked(event,false))throw new AssertionError("HQ click was not consumed: "+label);screen.mouseReleased(event);}
}
